def process(identity_theft_reports) -> pd.DataFrame:
    filtered = identity_theft_reports[
        (identity_theft_reports['Theft Type'] == 'Bank Account') & 
        (identity_theft_reports['Theft Subtype'] == 'New Accounts')
    ]
    return filtered

def process(report_type) -> pd.DataFrame:
    total = report_type[report_type['Report Type'] == 'Identity Theft']
    return total

def process(bank_account_new_accounts, total_identity_theft) -> pd.DataFrame:
    bank_account_new = bank_account_new_accounts['Number of Reports'].iloc[0]
    total_identity = total_identity_theft['Number of Reports'].iloc[0]
    proportion = bank_account_new / total_identity
    proportion_rounded = round(proportion, 4)
    return pd.DataFrame({'Proportion': [proportion_rounded]})
